(() => {
  'use strict';

  // Deliberately narrow selectors and explicit disclosure signals. This is a
  // conservative heuristic, not proof that a post was generated by AI.
  const POST_SELECTOR = [
    'article',
    '[role="article"]',
    '[data-testid="tweet"]',
    '.feed-shared-update-v2'
  ].join(', ');
  const UI_ATTR = 'data-ai-eraser-ui';
  const HIDDEN_ATTR = 'data-ai-eraser-hidden';
  const OVERRIDE_ATTR = 'data-ai-eraser-overridden';
  const SETTINGS_KEY = 'settings';
  const FEEDBACK_KEY = 'feedback';
  const RULES = [
    { id: 'ai-generated', label: 'Explicitly described as AI-generated', pattern: /\bai[ -]generated\b/i },
    { id: 'generated-by-ai', label: 'Explicitly says it was generated by AI', pattern: /\bgenerated\s+(?:entirely\s+)?by\s+(?:an?\s+)?ai\b/i },
    { id: 'made-with-ai', label: 'Explicitly described as made or created with AI', pattern: /\b(?:made|created|produced)\s+(?:entirely\s+)?with\s+(?:the\s+)?help\s+of\s+ai\b|\b(?:made|created|produced)\s+(?:entirely\s+)?using\s+ai\b/i },
    { id: 'ai-tool-disclosure', label: 'Names an AI image-generation tool as the creator', pattern: /\b(?:generated|created|made)\s+(?:with|using|by)\s+(?:midjourney|dall[ -]?e|stable diffusion)\b/i }
  ];
  const DEFAULT_SETTINGS = { autoHide: true };
  let settings = { ...DEFAULT_SETTINGS };
  const queuedPosts = new Set();
  let scheduled = false;

  function installStyles() {
    if (document.getElementById('ai-eraser-styles')) return;
    const style = document.createElement('style');
    style.id = 'ai-eraser-styles';
    style.textContent = `
      [${HIDDEN_ATTR}="true"] { display: none !important; }
      .ai-eraser-notice { box-sizing: border-box; margin: 8px 0; padding: 12px;
        border: 1px solid #b7791f; border-radius: 8px; background: #fffaf0;
        color: #242424; font: 14px/1.4 system-ui, sans-serif; }
      .ai-eraser-notice strong { display: block; margin-bottom: 4px; }
      .ai-eraser-notice button { margin: 8px 8px 0 0; padding: 6px 10px; cursor: pointer; }
    `;
    (document.head || document.documentElement).appendChild(style);
  }

  function findMatches(post) {
    const text = (post.innerText || post.textContent || '').slice(0, 20000);
    const matches = [];
    for (const rule of RULES) {
      if (rule.pattern.test(text)) matches.push(rule);
    }

    // Only inspect human-readable image labels. URLs are not reliable evidence.
    for (const image of post.querySelectorAll('img[alt], img[title]')) {
      const label = `${image.alt || ''} ${image.title || ''}`;
      for (const rule of RULES) {
        if (rule.pattern.test(label) && !matches.some((match) => match.id === rule.id)) {
          matches.push(rule);
        }
      }
    }
    return matches;
  }

  function getNotice(post) {
    const next = post.previousElementSibling;
    return next && next.classList.contains('ai-eraser-notice') ? next : null;
  }

  function recordFeedback(matches, verdict) {
    chrome.storage.local.get({ [FEEDBACK_KEY]: {} }, (result) => {
      const feedback = result[FEEDBACK_KEY] || {};
      feedback.totals = feedback.totals || { falsePositive: 0, confirmed: 0 };
      feedback.byRule = feedback.byRule || {};
      feedback.totals[verdict] = (feedback.totals[verdict] || 0) + 1;
      for (const rule of matches) {
        const counts = feedback.byRule[rule.id] || { falsePositive: 0, confirmed: 0 };
        counts[verdict] = (counts[verdict] || 0) + 1;
        feedback.byRule[rule.id] = counts;
      }
      chrome.storage.local.set({ [FEEDBACK_KEY]: feedback });
    });
  }

  function makeNotice(post, matches) {
    const notice = document.createElement('div');
    notice.className = 'ai-eraser-notice';
    notice.setAttribute(UI_ATTR, 'true');
    notice.setAttribute('role', 'status');

    const heading = document.createElement('strong');
    heading.textContent = settings.autoHide
      ? 'Hidden: this post contains an explicit AI disclosure.'
      : 'Possible AI disclosure found (post is not hidden).';
    notice.appendChild(heading);

    const explanation = document.createElement('div');
    explanation.textContent = `Why flagged: ${matches.map((match) => match.label).join('; ')}. This is a heuristic, not verification.`;
    notice.appendChild(explanation);

    const showButton = document.createElement('button');
    showButton.type = 'button';
    showButton.textContent = 'Show anyway (not AI)';
    showButton.addEventListener('click', () => {
      post.setAttribute(OVERRIDE_ATTR, 'true');
      post.removeAttribute(HIDDEN_ATTR);
      notice.remove();
      recordFeedback(matches, 'falsePositive');
    });
    notice.appendChild(showButton);

    const confirmButton = document.createElement('button');
    confirmButton.type = 'button';
    confirmButton.textContent = 'Confirm AI';
    confirmButton.addEventListener('click', () => {
      recordFeedback(matches, 'confirmed');
      confirmButton.disabled = true;
      confirmButton.textContent = 'Confirmation recorded';
    });
    notice.appendChild(confirmButton);

    return notice;
  }

  function evaluatePost(post) {
    if (!post.isConnected || post.closest(`[${UI_ATTR}]`)) return;
    if (post.hasAttribute(OVERRIDE_ATTR)) {
      post.removeAttribute(HIDDEN_ATTR);
      const notice = getNotice(post);
      if (notice) notice.remove();
      return;
    }

    const matches = findMatches(post);
    if (!matches.length) {
      post.removeAttribute(HIDDEN_ATTR);
      const notice = getNotice(post);
      if (notice) notice.remove();
      return;
    }

    post.toggleAttribute(HIDDEN_ATTR, settings.autoHide);
    let notice = getNotice(post);
    if (!notice) {
      notice = makeNotice(post, matches);
      post.parentNode.insertBefore(notice, post);
    } else {
      // Refresh the reason and buttons after a site's dynamic content update.
      const replacement = makeNotice(post, matches);
      notice.replaceWith(replacement);
    }
  }

  function queuePost(post) {
    if (!post || post.nodeType !== Node.ELEMENT_NODE || post.closest(`[${UI_ATTR}]`)) return;
    queuedPosts.add(post);
    if (scheduled) return;
    scheduled = true;
    requestAnimationFrame(() => {
      scheduled = false;
      for (const candidate of queuedPosts) evaluatePost(candidate);
      queuedPosts.clear();
    });
  }

  function inspectNode(node) {
    if (!node) return;
    const element = node.nodeType === Node.ELEMENT_NODE ? node : node.parentElement;
    if (!element || element.closest(`[${UI_ATTR}]`)) return;
    if (element.matches(POST_SELECTOR)) queuePost(element);
    const containingPost = element.closest(POST_SELECTOR);
    if (containingPost) queuePost(containingPost);
    element.querySelectorAll(POST_SELECTOR).forEach(queuePost);
  }

  function init() {
    if (!document.body) return;
    installStyles();
    chrome.storage.local.get({ [SETTINGS_KEY]: DEFAULT_SETTINGS }, (result) => {
      settings = { ...DEFAULT_SETTINGS, ...(result[SETTINGS_KEY] || {}) };
      inspectNode(document.body);
    });

    const observer = new MutationObserver((mutations) => {
      for (const mutation of mutations) {
        if (mutation.target.nodeType === Node.ELEMENT_NODE && mutation.target.closest(`[${UI_ATTR}]`)) continue;
        if (mutation.type === 'attributes' || mutation.type === 'characterData') {
          inspectNode(mutation.target);
        } else {
          mutation.addedNodes.forEach(inspectNode);
        }
      }
    });
    observer.observe(document.body, {
      childList: true, subtree: true, characterData: true,
      attributes: true, attributeFilter: ['src', 'alt', 'title']
    });

    chrome.storage.onChanged.addListener((changes, area) => {
      if (area !== 'local' || !changes[SETTINGS_KEY]) return;
      settings = { ...DEFAULT_SETTINGS, ...(changes[SETTINGS_KEY].newValue || {}) };
      document.querySelectorAll(POST_SELECTOR).forEach(queuePost);
    });
  }

  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', init, { once: true });
  } else {
    init();
  }
})();
